pages/product:
---
product:
    videos:
        limit: {{theme_settings.productpage_videos_count}}
    reviews:
        limit: {{theme_settings.productpage_reviews_count}}
    related_products:
        limit: {{theme_settings.productpage_related_products_count}}
    similar_by_views:
        limit: {{theme_settings.productpage_similar_by_views_count}}
cart: true
---
{{inject 'productId' product.id}}

{{#partial "page"}}

    <div class="container">
        <div class="product-page--breadcrumb breadcrumb-pc">
            {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
        </div>
        <div class="product-page--breadcrumb breadcrumb-mobile">
            {{> components/custom/product/product-breadcrumbs breadcrumbs=breadcrumbs}}
        </div>
    
    
    </div>

    {{#each product.shipping_messages}}
        {{> components/common/alert/alert-info message}}
    {{/each}}

    <div itemscope itemtype="https://schema.org/Product">
        {{> components/products/product-view }}

        {{{region name="product_below_content"}}}

        <div class="container">
            {{#if product.videos.list.length}}
                
            {{/if}}

            {{#if theme_settings.its.pdp_carousel_tabs}}
                {{> components/products/tabs}}
            {{else}}
                {{#if product.related_products}}
                    <h2 class="productCarousel-heading productCarousel-heading--related h1">{{lang 'products.related_products'}}</h2>
                    {{#if settings.data_tag_enabled}}
                        {{> components/products/carousel products=product.related_products columns=6 list="Related Products"}}
                    {{else}}
                        {{> components/products/carousel products=product.related_products columns=6 }}
                    {{/if}}
                {{/if}}
            {{/if}}
            {{{region name="product_below_related"}}}

            {{#all settings.show_product_reviews theme_settings.show_product_reviews}}
                {{> components/products/reviews reviews=product.reviews product=product urls=urls}}
            {{/all}}

            {{{region name="videos_and_articles"}}}
        </div>
    </div>
    {{> components/custom/photoswipe}}
    {{> components/products/schema}}
{{/partial}}

{{> layout/base container_active=false}}

